create table public.news_observations(id uuid primary key default gen_random_uuid(),observation_key text not null unique,observation_version text not null,asset_id uuid not null references public.assets(id),provider text not null,provider_article_id text not null,headline text not null,summary text,url text not null,source_name text not null,source_classification text not null check(source_classification in('OFFICIAL_SOURCE','PRIMARY_MEDIA','REPUTABLE_SECONDARY','SOCIAL_VERIFIED','SOCIAL_UNVERIFIED','UNKNOWN')),occurred_at timestamptz not null,observed_at timestamptz not null,available_at timestamptz not null,data_quality integer not null check(data_quality between 0 and 100),raw_payload jsonb not null default'{}',created_at timestamptz not null default now(),check(occurred_at<=observed_at and observed_at<=available_at),unique(provider,provider_article_id,asset_id));
create or replace function public.prevent_news_observation_mutation()returns trigger language plpgsql as $$begin raise exception'News observations are immutable';end$$;create trigger news_observations_immutable before update or delete on public.news_observations for each row execute function public.prevent_news_observation_mutation();alter table public.news_observations enable row level security;create policy "public read news observations" on public.news_observations for select using(true);grant select on public.news_observations to anon,authenticated;grant all on public.news_observations to service_role;
alter table public.ingestion_runs drop constraint if exists ingestion_runs_job_kind_check;alter table public.ingestion_runs add constraint ingestion_runs_job_kind_check check(job_kind in('stock_quotes','wallet_transactions','wallet_discovery','crypto_market','wallet_pnl','wallet_evidence','fast_flow','wallet_clustering','jackpot_collector','jackpot_outcomes','market_events','paper_eligibility','paper_execution','paper_exits','paper_valuation','performance','fx','qualification','data_gap_closure','simulation','historical_replay','forecast_catalyst','expert_knowledge','baseline_forecast','forecast_performance','forecast_scheduler','forecast_outcomes','specialist_agents','news_ingestion'));
